CREATE TABLE IF NOT EXISTS `month` (id INT AUTO_INCREMENT PRIMARY KEY, period VARCHAR(7) NOT NULL, capital DECIMAL(18, 6) NOT NULL, `floor` DECIMAL(18, 6) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL);
ALTER TABLE `month` ADD CONSTRAINT month_period_unique UNIQUE (period);
CREATE TABLE IF NOT EXISTS target (id INT AUTO_INCREMENT PRIMARY KEY, month_id INT NOT NULL, `level` VARCHAR(20) NOT NULL, asset_class VARCHAR(20) NULL, strategy VARCHAR(100) NULL, sub_class VARCHAR(20) NULL, ticker VARCHAR(12) NULL, percentage DECIMAL(18, 6) NOT NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_target_month_id__id FOREIGN KEY (month_id) REFERENCES `month`(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
